                    assertTrue(false, "settle reverted, payout guarantee broken");
                }
            } else {
                // guess didn't match, property vacuously holds for settle
                assertTrue(true);
            }
        } catch {
            // lock reverted, property vacuously holds
            assertTrue(true);
        }
    }
