pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guess) public {
        // lock in a guess with exactly 1 ether
        vm.deal(address(this), 1 ether);
        c.lockInGuess{value: 1 ether}(guess);

        // immediately try to settle (block.number hasn't advanced,
        // so guesses[address(this)].block is still current block + 1 in the reference,
        // but current block in the mutant).
        // In the reference, block.number > block+1 is false → revert.
        // In the mutant,  block.number == block  → settle reverts with "require(block.number > guesses[msg.sender].block)" anyway.
        // We need a single assertion that holds always for ref and breaks for mutant.
        // After the above, the stored block is set. We roll forward exactly 1 block.
        vm.roll(block.number + 1);

        // After advancing by 1 block, in the reference stored block = initial+1,
        // now block.number = stored block → require(block.number > stored block) still fails.
        // In the mutant stored block = initial block, now block.number = initial+1 > initial block,
        // so settle proceeds and may reward if guess equals blockhash(initial block).
        // Because the blockhash was already fixed before the lockInGuess call,
        // we can compute it and supply it as the fuzzed guess.
        // The property: after lockInGuess at block N and rolling to N+1, the contract's
        // balance never decreases, because settle must revert.
        uint256 balBefore = address(c).balance;
        try c.settle() {} catch {}
        uint256 balAfter = address(c).balance;
        assertEq(balAfter, balBefore, "balance must not decrease");
    }
}

