pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 blockOffset1, uint256 blockOffset2) public {
        // Ensure at least one block passes between lockInGuess and settle
        bound(blockOffset1, 2, 100);
        bound(blockOffset2, blockOffset1 + 1, 200);
        address player = makeAddr("player");
        vm.deal(player, 1 ether);
        vm.deal(address(c), 2 ether);

        // lockInGuess with the fuzzed hash
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks past lockInGuess block
        vm.roll(blockOffset1);
        // Warp to the block after lockInGuess's recorded block
        vm.warp(blockOffset1 + 1);

        // Record player balance before settle
        uint256 balanceBefore = player.balance;

        vm.prank(player);
        c.settle();

        uint256 balanceAfter = player.balance;

        // If the guess equals the expected blockhash, reference pays 2 ether, mutant generally does not
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(blockOffset1)));
        if (hash == expectedAnswer) {
            assertEq(balanceAfter - balanceBefore, 2 ether);
        } else {
            assertEq(balanceAfter, balanceBefore);
        }
    }
}

