    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 blockOffset) public {
        vm.assume(blockOffset > 0 && blockOffset < 256);
        address alice = makeAddr("alice");
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(hash);
        vm.roll(block.number + blockOffset);
        uint256 balBefore = address(c).balance;
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(address(c).balance == balBefore - 2 ether);
        } else {
            assertTrue(true);
        }
    }
}

