pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockBefore, uint256 blockAfter, bytes32 hash1, bytes32 hash2) public {
        vm.assume(blockBefore < blockAfter);
        vm.assume(blockBefore > 0);
        vm.assume(blockAfter > 0);

        address actor = address(0x100);
        vm.deal(actor, 2 ether);

        // First lockInGuess at blockBefore
        vm.roll(blockBefore);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash1);

        // Second lockInGuess at blockAfter
        vm.roll(blockAfter);
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(hash2) { } catch { }

        // Get the stored block after both calls
        (uint storedBlock, ) = c.guesses(actor);
        // In reference, second call reverts (storedBlock stays blockBefore+1). In buggy, overwrite succeeds (storedBlock becomes blockAfter+1).
        // The invariant: storedBlock must not exceed the first recorded block (blockBefore+1) — because second call should have reverted.
        // Equivalently, storedBlock <= blockBefore+1 is always true for reference; buggy can make it larger.
        assertTrue(storedBlock <= blockBefore + 1);
    }
}

