pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, bytes32 hash1, bytes32 hash2, uint48 timeSkip) public {
        vm.assume(actor != address(0));
        vm.assume(timeSkip > 0);
        vm.deal(actor, 2 ether);

        // First lock-in
        uint256 blockBeforeFirst = block.number;
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash1);
        (uint256 storedBlock1,) = c.guesses(actor);

        // Warp past the first lock-in block to make it settlable, simulating time passage
        vm.roll(block.number + timeSkip + 1);

        // Second lock-in (potentially overwriting if bug present)
        uint256 blockBeforeSecond = block.number;
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash2);

        (uint256 storedBlock2,) = c.guesses(actor);

        // Settle to see which blockhash is used
        vm.roll(block.number + timeSkip + 1);
        vm.prank(actor);
        c.settle();

        uint256 balanceAfter = address(c).balance;

        // The general rule: after two successful lockInGuess calls followed by a settle,
        // if the second overwrote the first (bug), the contract only has 1 ether (the second deposit).
        // The correct contract retains 2 ether because the first guess is settled independently.
        // So we assert that balanceAfter must be exactly 2 ether (correct behavior).
        assertTrue(balanceAfter == 2 ether, "Contract balance should reflect both deposits");
    }
}

